do $$
declare uid uuid:=gen_random_uuid(); other_uid uuid:=gen_random_uuid(); sid uuid:=gen_random_uuid(); sid2 uuid:=gen_random_uuid();
  old_id uuid:=gen_random_uuid(); new_id uuid:=gen_random_uuid(); foreign_id uuid:=gen_random_uuid(); ip text:=repeat('a',64); agent text:=repeat('b',64);
  value jsonb; codes jsonb; expiry timestamptz;
begin
  insert into auth.users(id,email,email_confirmed_at) values(uid,'rotation-'||uid||'@example.invalid',clock_timestamp()),(other_uid,'rotation-'||other_uid||'@example.invalid',clock_timestamp());
  insert into public.users(id,email,username,full_name,role,status) values(uid,'rotation-'||uid||'@example.invalid','rotation-'||uid,'Rotation fixture','user','active') on conflict(id) do update set role='user',status='active';
  insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) values(old_id,uid,'totp','verified','fixture-only',clock_timestamp(),clock_timestamp()),(foreign_id,other_uid,'totp','unverified','fixture-only',clock_timestamp(),clock_timestamp());
  insert into auth.sessions(id,user_id,aal,factor_id,created_at,updated_at) values(sid,uid,'aal2',old_id,clock_timestamp(),clock_timestamp()),(sid2,uid,'aal2',old_id,clock_timestamp(),clock_timestamp());
  insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values(gen_random_uuid(),sid,'totp',clock_timestamp(),clock_timestamp()),(gen_random_uuid(),sid2,'totp',clock_timestamp(),clock_timestamp());
  insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values(gen_random_uuid(),sid,'password',clock_timestamp(),clock_timestamp()),(gen_random_uuid(),sid2,'password',clock_timestamp(),clock_timestamp());
  perform set_config('request.jwt.claims',jsonb_build_object('role','service_role')::text,true);
  value:=public.security_service('register',uid,sid,ip,agent);
  perform public.security_service('register',uid,sid2,ip,agent);
  update management_security.sessions set email_required=false,authorized_at=clock_timestamp() where user_id=uid;
  update management_security.accounts set recovery_ack_at=clock_timestamp() where user_id=uid;
  select expires_at into expiry from management_security.sessions where session_id=sid;
  if public.security_totp_replacement('begin',uid,sid,repeat('c',64),agent,old_id)->>'ok'<>'false' then raise exception 'Wrong IP accepted'; end if;
  if public.security_totp_replacement('begin',uid,sid,ip,agent,foreign_id)->>'ok'<>'false' then raise exception 'Foreign factor accepted'; end if;
  update auth.mfa_amr_claims set updated_at=clock_timestamp()-interval '1 minute' where session_id=sid;
  if public.security_totp_replacement('begin',uid,sid,ip,agent,old_id)->>'ok'<>'false' then raise exception 'Stale current proof accepted'; end if;
  update auth.mfa_amr_claims set updated_at=clock_timestamp() where session_id=sid;
  if public.security_totp_replacement('begin',uid,sid,ip,agent,old_id)->>'ok'<>'true' then raise exception 'Begin rejected'; end if;
  if public.security_totp_replacement('begin',uid,sid2,ip,agent,old_id)->>'ok'<>'false' then raise exception 'Concurrent rotation accepted'; end if;
  insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) values(new_id,uid,'totp','unverified','fixture-only',clock_timestamp(),clock_timestamp());
  if public.security_totp_replacement('register',uid,sid,ip,agent,null,foreign_id)->>'ok'<>'false' then raise exception 'Foreign enrollment accepted'; end if;
  if public.security_totp_replacement('register',uid,sid,ip,agent,null,new_id)->>'ok'<>'true' then raise exception 'Register rejected'; end if;
  if public.security_totp_replacement('finish',uid,sid,ip,agent,old_id,new_id)->>'ok'<>'false' then raise exception 'Unverified new factor retired old'; end if;
  if not exists(select 1 from auth.mfa_factors where id=old_id and status='verified') then raise exception 'Old factor was removed prematurely'; end if;
  if public.security_totp_replacement('cancel',uid,sid,ip,agent)->>'ok'<>'true' then raise exception 'Cancel rejected'; end if;
  if exists(select 1 from auth.mfa_factors where id=new_id) or not exists(select 1 from auth.mfa_factors where id=old_id) then raise exception 'Cancel removed wrong factor'; end if;
  perform public.security_totp_replacement('begin',uid,sid,ip,agent,old_id);
  insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) values(new_id,uid,'totp','unverified','fixture-only',clock_timestamp(),clock_timestamp());
  perform public.security_totp_replacement('register',uid,sid,ip,agent,null,new_id);
  update auth.mfa_factors set status='verified' where id=new_id;
  if public.security_totp_replacement('cancel',uid,sid,ip,agent)->>'ok'<>'false' then raise exception 'Verified replacement cancelled'; end if;
  update auth.sessions set factor_id=new_id where id=sid;
  update auth.mfa_amr_claims set updated_at=clock_timestamp() where session_id=sid;
  if public.security_totp_replacement('verified',uid,sid,ip,agent,null,new_id)->>'ok'<>'true' then raise exception 'Rotation rejected'; end if;
  if exists(select 1 from auth.mfa_factors where id=old_id) or not exists(select 1 from auth.mfa_factors where id=new_id and status='verified') then raise exception 'Wrong final factors'; end if;
  if not management_security.live(uid,sid,ip) or management_security.live(uid,sid2,ip) then raise exception 'Wrong session retained/revoked'; end if;
  if (select expires_at from management_security.sessions where session_id=sid) is distinct from expiry then raise exception 'Rotation extended session'; end if;
  if (select recovery_ack_at from management_security.accounts where user_id=uid) is not null then raise exception 'Recovery acknowledgement bypass'; end if;
  if public.security_totp_replacement('finish',uid,sid,ip,agent,old_id,new_id)->>'ok'<>'true' then raise exception 'Idempotent retry rejected'; end if;
  codes:=public.security_service('recovery_issue',uid,sid,ip,agent);
  if jsonb_array_length(codes->'codes')<>10 then raise exception 'Recovery bundle missing'; end if;
  perform public.security_service('recovery_ack',uid,sid,ip,agent,jsonb_build_object('batch_id',codes->>'batch_id'));
  if public.security_service('authorize',uid,sid,ip,agent)->>'ok'<>'true' then raise exception 'Saved recovery failed to authorize'; end if;
  update auth.mfa_amr_claims set updated_at=clock_timestamp()-interval '6 minutes' where session_id=sid and authentication_method='totp';
  if public.security_overview_read(uid,sid,ip,agent)->>'ok'<>'true' then raise exception 'Read-only overview required fresh MFA'; end if;
  if public.security_overview_read(uid,sid,repeat('c',64),agent)->>'ok'<>'false' then raise exception 'Overview wrong IP accepted'; end if;
  if public.security_overview_read(uid,sid,ip,repeat('c',64))->>'ok'<>'false' then raise exception 'Overview wrong browser accepted'; end if;
  if public.security_overview_read(other_uid,sid,ip,agent)->>'ok'<>'false' then raise exception 'Overview foreign identity accepted'; end if;
  begin perform public.security_service('device_create',uid,sid,ip,agent,jsonb_build_object('token_hash',repeat('d',64))); raise exception 'Stale MFA mutated device'; exception when insufficient_privilege then null; end;
  update management_security.sessions set expires_at=clock_timestamp()-interval '1 second' where session_id=sid;
  if public.security_overview_read(uid,sid,ip,agent)->>'ok'<>'false' then raise exception 'Expired overview accepted'; end if;
  update management_security.sessions set expires_at=expiry where session_id=sid;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid,'aal','aal2')::text,true);
  if not public.security_management_access_allowed(false) then raise exception 'Completed rotation lost access'; end if;
  begin perform public.security_totp_replacement('cancel',uid,sid,ip,agent); raise exception 'Public rotation RPC bypass'; exception when insufficient_privilege then null; end;
  begin perform public.security_overview_read(uid,sid,ip,agent); raise exception 'Public overview RPC bypass'; exception when insufficient_privilege then null; end;
end $$;
select 'passed' as totp_replacement_invariants;
